-- Story #325: managed venue categories
-- A staff-managed list of venue categories, and the links from venues to their categories.
-- Idempotent: safe to re-run. Re-running never overwrites a category staff have renamed or deactivated.
--
-- Run against the right database first and check which server you are on:
--   SELECT current_database(), inet_server_addr();

BEGIN;

CREATE TABLE IF NOT EXISTS public."VenueCategories" (
    "VenueCategoryID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(100) NOT NULL,
    "Slug" varchar(100) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT true,
    "SortOrder" integer NOT NULL DEFAULT 0
);

-- The slug is the stable key used by filters, and two categories can't share a name in any letter case.
CREATE UNIQUE INDEX IF NOT EXISTS "IX_VenueCategories_Slug"
    ON public."VenueCategories" ("Slug");

CREATE UNIQUE INDEX IF NOT EXISTS "IX_VenueCategories_Name_Lower"
    ON public."VenueCategories" (lower("Name"));

CREATE TABLE IF NOT EXISTS public."Linker_VenueToCategory" (
    "Linker_VenueToCategoryID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "VenueID" integer NOT NULL,
    "VenueCategoryID" integer NOT NULL
);

-- A venue has a given category at most once.
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Linker_VenueToCategory_VenueID_VenueCategoryID"
    ON public."Linker_VenueToCategory" ("VenueID", "VenueCategoryID");

-- Used when filtering venues by category.
CREATE INDEX IF NOT EXISTS "IX_Linker_VenueToCategory_VenueCategoryID"
    ON public."Linker_VenueToCategory" ("VenueCategoryID");

DO $migration$
BEGIN
    -- Links are removed together with their venue.
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'FK_Linker_VenueToCategory_Venues_VenueID' AND conrelid = 'public."Linker_VenueToCategory"'::regclass
    ) THEN
        ALTER TABLE public."Linker_VenueToCategory"
            ADD CONSTRAINT "FK_Linker_VenueToCategory_Venues_VenueID"
            FOREIGN KEY ("VenueID") REFERENCES public."Venues" ("VenueID") ON DELETE CASCADE;
    END IF;

    -- Categories are deactivated, never deleted, so a category that venues still use can't be removed.
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'FK_Linker_VenueToCategory_VenueCategories_VenueCategoryID' AND conrelid = 'public."Linker_VenueToCategory"'::regclass
    ) THEN
        ALTER TABLE public."Linker_VenueToCategory"
            ADD CONSTRAINT "FK_Linker_VenueToCategory_VenueCategories_VenueCategoryID"
            FOREIGN KEY ("VenueCategoryID") REFERENCES public."VenueCategories" ("VenueCategoryID") ON DELETE RESTRICT;
    END IF;
END
$migration$;

-- Starter categories. A row that already exists (same slug or same name) is left exactly as it is.
INSERT INTO public."VenueCategories" ("Name", "Slug", "IsActive", "SortOrder") VALUES
    ('Camping grounds',      'camping-grounds',      true, 10),
    ('Theaters',             'theaters',             true, 20),
    ('Bars',                 'bars',                 true, 30),
    ('Galleries',            'galleries',            true, 40),
    ('Clubs',                'clubs',                true, 50),
    ('Convention centers',   'convention-centers',   true, 60),
    ('Studios',              'studios',              true, 70),
    ('Other event spaces',   'other-event-spaces',   true, 80)
ON CONFLICT DO NOTHING;

COMMIT;
